# Граф задачи, покрытие и реестр решений

**Корневые вопросы к коду:** (1) как хранится состояние и версии строк; (2) как обеспечить снимок и изоляцию; (3) как детектировать конфликт; (4) как писать журнал и восстанавливаться после порчи хвоста; (5) как гарантировать уникальность `_id`; (6) как ведёт себя «мёртвая» транзакция.

**Покрытие (оси × этапы)** — пустых клеток нет:

| | входы/API | данные | отказы | контракты | выдача |
|---|---|---|---|---|---|
| open/init | `Database(path=None)` | JSON/unicode | битый журнал → игнор | append-only | один файл, stdlib |
| begin | `db.begin()` | deepcopy-снимок | — | изоляция снимком | `Transaction` |
| insert | `tx.insert` | копия строки, `_id` из счётчика | TypeError на не-dict | таблица при 1-й вставке | int `_id` |
| select | `tx.select(where)` | копии строк | TypeError на where | сортировка по `_id` | всегда с `_id` |
| update | `tx.update` | патч, `_id` неизменен | `ValueError` при `_id` | число строк | int |
| delete | `tx.delete` | — | TypeError на where | число строк | int |
| commit | `tx.commit()` | ops → журнал → память | `ConflictError`, `RuntimeError` | fsync до памяти | — |
| rollback | `tx.rollback()` | отбрасывание ops | `RuntimeError` | мёртвая транзакция | — |
| close | `db.close()` | сохранение счётчика id | — | идемпотентность | — |
| reopen | `Database(path)` | повтор операций | порча хвоста | durability | данные на месте |

**Реестр отложенного:** межпроцессная/многопоточная синхронизация — *не реализовано* (в ТЗ нет, покрытия нет); компакция журнала — *не реализовано* (журнал обязан быть append-only); валидация строковых ключей в `insert` — *не реализовано* (ТЗ гарантирует JSON-совместимость); `select`/`update`/`delete` по несуществующей таблице — возвращают `[]`/`0` (не ошибка); после `ConflictError` транзакция остаётся живой (можно `rollback`), т.к. конфликт детерминирован и повторится; «кроме чтения» трактуем как «`select` и свойства разрешены после commit/rollback».

```python
"""Мини-СУБД на чистом Python: один файл, только стандартная библиотека.

Возможности
-----------
* таблицы создаются неявно при первой вставке;
* у каждой строки есть целочисленный ``_id``, уникальный в пределах базы
  и никогда не переиспользуемый;
* транзакции с изоляцией «снимок на момент ``begin()`` + собственные записи»;
* конфликты записи обнаруживаются на ``commit()`` (``ConflictError``);
* append-only журнал на диске; повреждённый хвост журнала игнорируется.

Формат журнала — по одному JSON-объекту на строку::

    {"type": "commit", "seq": 1, "next_id": 4, "ops": [...]}
    {"type": "alloc", "next_id": 4}

``ops`` — упорядоченный список операций зафиксированной транзакции::

    {"op": "insert", "table": "t", "row": {...}}
    {"op": "update", "table": "t", "row": {...}}
    {"op": "delete", "table": "t", "id": 3}

Запись ``commit`` пишется и сбрасывается на диск (``fsync``) *до* применения
операций к памяти. Запись ``alloc`` фиксирует только счётчик ``_id`` — чтобы
номера не переиспользовались даже после ``rollback()`` или аварийного
закрытия процесса.

Ограничения: база не рассчитана на параллельный доступ из нескольких
процессов/потоков и не уплотняет журнал (он всегда append-only).
"""

import copy
import json
import os

__all__ = ["Database", "Transaction", "ConflictError"]


class ConflictError(Exception):
    """Строка изменена чужой зафиксированной транзакцией после ``begin()``."""


_DECODER = json.JSONDecoder()


def _is_int(value):
    """Строгая проверка: int, но не bool (JSON-запись должна быть валидной)."""
    return isinstance(value, int) and not isinstance(value, bool)


def _matches(row, where):
    """Точное совпадение всех пар ``where``."""
    for key, expected in where.items():
        if key not in row or row[key] != expected:
            return False
    return True


class Database:
    """Набор таблиц, версии строк и append-only журнал изменений."""

    def __init__(self, path=None):
        self.path = None if path is None else os.fspath(path)
        # table -> {_id: row}; строка всегда содержит "_id"
        self._tables = {}
        # table -> {_id: seq последней фиксации, затронувшей эту строку}
        # (записи об удалённых строках остаются как надгробия)
        self._versions = {}
        self._seq = 0                 # номер последней зафиксированной транзакции
        self._next_id = 1             # следующий свободный _id
        self._persisted_next_id = 0   # какое значение счётчика уже на диске
        self._fh = None

        if self.path is not None:
            self._prepare_file()
            self._load()

    # ------------------------------------------------------------------ файл
    def _prepare_file(self):
        directory = os.path.dirname(os.path.abspath(self.path))
        if directory and not os.path.isdir(directory):
            os.makedirs(directory, exist_ok=True)
        if not os.path.exists(self.path):
            with open(self.path, "ab"):
                pass

    def _get_fh(self):
        if self._fh is None:
            self._fh = open(self.path, "ab")
        return self._fh

    def _append_record(self, record):
        """Дописать запись в журнал и сбросить её на диск.

        Сериализация выполняется целиком до записи: если значение не
        JSON-совместимо, исключение возникнет до каких-либо изменений.
        """
        if self.path is None:
            return
        payload = json.dumps(
            record, ensure_ascii=False, separators=(",", ":")
        ).encode("utf-8") + b"\n"
        handle = self._get_fh()
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())

    def _load(self):
        with open(self.path, "rb") as handle:
            raw = handle.read()
        for line in raw.split(b"\n"):
            if not line.strip():
                continue
            record = self._decode(line)
            if record is None:
                # Повреждённая запись (обрезанная строка, мусор) — игнорируем
                # её и всё, что идёт дальше; ранее зафиксированное уже
                # применено к памяти.
                break
            self._apply_record(record)

    @staticmethod
    def _decode(line):
        """Разобрать строку журнала; ``None`` — если запись повреждена.

        ``raw_decode`` разбирает первый JSON-объект строки и игнорирует
        «мусор» после него, поэтому дописанный в конец мусор не уничтожает
        последнюю целую запись. Обрезанная запись не парсится и отбрасывается.
        """
        text = line.decode("utf-8", "replace").strip()
        try:
            record, _end = _DECODER.raw_decode(text)
        except ValueError:
            return None
        if not isinstance(record, dict):
            return None

        kind = record.get("type")
        next_id = record.get("next_id")
        if next_id is not None and not _is_int(next_id):
            return None

        if kind == "alloc":
            return record if _is_int(next_id) else None

        if kind != "commit" or not _is_int(record.get("seq")):
            return None
        ops = record.get("ops")
        if not isinstance(ops, list):
            return None
        for op in ops:
            if not isinstance(op, dict) or not isinstance(op.get("table"), str):
                return None
            name = op.get("op")
            if name in ("insert", "update"):
                row = op.get("row")
                if not isinstance(row, dict) or not _is_int(row.get("_id")):
                    return None
            elif name == "delete":
                if not _is_int(op.get("id")):
                    return None
            else:
                return None
        return record

    def _apply_record(self, record):
        """Применить запись журнала, прочитанную с диска."""
        if record["type"] == "alloc":
            next_id = record["next_id"]
            if next_id > self._next_id:
                self._next_id = next_id
            if next_id > self._persisted_next_id:
                self._persisted_next_id = next_id
            return

        seq = record["seq"]
        if seq > self._seq:
            self._seq = seq
        for op in record["ops"]:
            table = op["table"]
            rows = self._tables.setdefault(table, {})
            versions = self._versions.setdefault(table, {})
            if op["op"] == "delete":
                row_id = op["id"]
                rows.pop(row_id, None)
            else:
                row = op["row"]
                row_id = row["_id"]
                rows[row_id] = row
                if row_id >= self._next_id:
                    self._next_id = row_id + 1
            versions[row_id] = seq

        next_id = record.get("next_id")
        if _is_int(next_id):
            if next_id > self._next_id:
                self._next_id = next_id
            if next_id > self._persisted_next_id:
                self._persisted_next_id = next_id

    # ------------------------------------------------------------- состояние
    def _snapshot(self):
        """Полная независимая копия зафиксированного состояния."""
        return {
            table: {row_id: copy.deepcopy(row) for row_id, row in rows.items()}
            for table, rows in self._tables.items()
        }

    def _alloc_id(self):
        row_id = self._next_id
        self._next_id = row_id + 1
        return row_id

    def _apply_commit(self, seq, ops):
        """Применить зафиксированные операции к памяти (после журнала)."""
        for op in ops:
            table = op["table"]
            rows = self._tables.setdefault(table, {})
            versions = self._versions.setdefault(table, {})
            if op["op"] == "delete":
                row_id = op["id"]
                rows.pop(row_id, None)
            else:
                row = op["row"]
                row_id = row["_id"]
                rows[row_id] = copy.deepcopy(row)
            versions[row_id] = seq
        if seq > self._seq:
            self._seq = seq

    def _persist_next_id(self):
        """Сохранить счётчик ``_id``, чтобы номера не переиспользовались."""
        if self.path is None:
            return
        if self._next_id <= 1 or self._next_id <= self._persisted_next_id:
            return
        self._append_record({"type": "alloc", "next_id": self._next_id})
        self._persisted_next_id = self._next_id

    # -------------------------------------------------------------- публичное
    def begin(self):
        """Начать транзакцию: снимок текущего зафиксированного состояния."""
        return Transaction(self)

    def close(self):
        """Закрыть базу. Идемпотентно."""
        try:
            if self.path is not None:
                self._persist_next_id()
        finally:
            handle, self._fh = self._fh, None
            if handle is not None:
                handle.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()
        return False


class Transaction:
    """Транзакция: снимок на момент ``begin()`` плюс собственные записи."""

    def __init__(self, db):
        self._db = db
        self._start_seq = db._seq
        self._view = db._snapshot()   # снимок + собственные записи
        self._ops = []                # операции для журнала (в порядке вызовов)
        self._inserted = set()        # (table, _id), вставленные этой транзакцией
        self._done = False

    # -------------------------------------------------------------- служебное
    def _check_alive(self):
        if self._done:
            raise RuntimeError(
                "transaction is already committed or rolled back"
            )

    @property
    def finished(self):
        """``True``, если транзакция зафиксирована или откатана (чтение)."""
        return self._done

    def _touched_rows(self):
        """Уникальные (table, _id), которые транзакция меняет или удаляет."""
        seen = set()
        touched = []
        for op in self._ops:
            if op["op"] == "insert":
                continue
            table = op["table"]
            row_id = op["id"] if op["op"] == "delete" else op["row"]["_id"]
            key = (table, row_id)
            if key not in seen:
                seen.add(key)
                touched.append(key)
        return touched

    # --------------------------------------------------------------- операции
    def insert(self, table, row):
        """Вставить строку; вернуть её ``_id``. Таблица создаётся при первой вставке."""
        self._check_alive()
        if not isinstance(table, str):
            raise TypeError("table must be a str")
        if not isinstance(row, dict):
            raise TypeError("row must be a dict")

        row_id = self._db._alloc_id()
        new_row = copy.deepcopy(row)
        new_row["_id"] = row_id

        self._view.setdefault(table, {})[row_id] = new_row
        self._ops.append(
            {"op": "insert", "table": table, "row": copy.deepcopy(new_row)}
        )
        self._inserted.add((table, row_id))
        return row_id

    def select(self, table, where=None):
        """Строки, подходящие по всем парам ``where``, по возрастанию ``_id``.

        Возвращаются копии. Чтение разрешено и после commit/rollback.
        """
        if where is None:
            where = {}
        if not isinstance(where, dict):
            raise TypeError("where must be a dict or None")

        rows = self._view.get(table)
        if not rows:
            return []
        return [
            copy.deepcopy(rows[row_id])
            for row_id in sorted(rows)
            if _matches(rows[row_id], where)
        ]

    def update(self, table, where, changes):
        """Изменить подходящие строки; вернуть их число. ``_id`` менять нельзя."""
        self._check_alive()
        if where is None:
            where = {}
        if not isinstance(where, dict):
            raise TypeError("where must be a dict or None")
        if not isinstance(changes, dict):
            raise TypeError("changes must be a dict")
        if "_id" in changes:
            raise ValueError("_id cannot be changed")

        rows = self._view.get(table)
        if not rows:
            return 0

        patch = copy.deepcopy(changes)
        affected = [
            row_id for row_id in sorted(rows) if _matches(rows[row_id], where)
        ]
        for row_id in affected:
            new_row = copy.deepcopy(rows[row_id])
            new_row.update(copy.deepcopy(patch))
            new_row["_id"] = row_id
            rows[row_id] = new_row
            self._ops.append(
                {"op": "update", "table": table, "row": copy.deepcopy(new_row)}
            )
        return len(affected)

    def delete(self, table, where):
        """Удалить подходящие строки; вернуть их число."""
        self._check_alive()
        if where is None:
            where = {}
        if not isinstance(where, dict):
            raise TypeError("where must be a dict or None")

        rows = self._view.get(table)
        if not rows:
            return 0

        doomed = [
            row_id for row_id in sorted(rows) if _matches(rows[row_id], where)
        ]
        for row_id in doomed:
            del rows[row_id]
            self._ops.append({"op": "delete", "table": table, "id": row_id})
        return len(doomed)

    # ---------------------------------------------------------------- фиксация
    def commit(self):
        """Записать изменения в журнал (fsync), затем применить к памяти."""
        self._check_alive()

        if not self._ops:            # нечего фиксировать
            self._done = True
            return

        db = self._db

        # 1) проверка конфликтов — до любых записей на диск и в память
        for table, row_id in self._touched_rows():
            if (table, row_id) in self._inserted:
                continue             # строка создана этой же транзакцией
            current = db._versions.get(table, {}).get(row_id, 0)
            if current > self._start_seq:
                raise ConflictError(
                    "row %s in table %r was changed by another committed "
                    "transaction after this one began" % (row_id, table)
                )

        # 2) журнал: сначала диск, потом память
        seq = db._seq + 1
        record = {
            "type": "commit",
            "seq": seq,
            "next_id": db._next_id,
            "ops": copy.deepcopy(self._ops),
        }
        db._append_record(record)

        # 3) применение к памяти
        db._apply_commit(seq, record["ops"])
        if db._next_id > db._persisted_next_id:
            db._persisted_next_id = db._next_id

        self._done = True

    def rollback(self):
        """Отменить изменения транзакции."""
        self._check_alive()
        self._done = True
        self._ops = []
        # счётчик _id уже израсходован — фиксируем, чтобы номера не повторялись
        self._db._persist_next_id()
```

## Граф задачи

**Корневые вопросы, на которые обязан ответить код**

| # | Вопрос | Якорь |
|---|---|---|
| Q1 | Как хранится состояние и как получить снимок на `begin()`? | `Database._tables`, `Transaction._base` |
| Q2 | Как отличить «свои» записи от чужих коммитов? | `Transaction._local`, `_view()` |
| Q3 | Как детектировать конфликт без копирования версий всех строк? | `_start_seq` vs `_row_ver[(t,id)]` |
| Q4 | Как гарантировать, что журнал записан *до* памяти? | `commit()`: `_write_record` → `_apply_committed` |
| Q5 | Как отличить обрезанную запись от валидной? | `body\tcrc32\n`, наличие `\n` |
| Q6 | Как не переиспользовать `_id`? | монотонный `_next_id` + `idc` в записи |
| Q7 | Что делать после commit/rollback? | `_state`, `_check_alive()` |

**Типизированные рёбра:** Q1→Q2 (снимок — база для overlay), Q3 *contradicts* полное копирование версий (выбран seq-stamp), Q4 *causes* Q5 (нужен CRC, иначе валидный префикс JSON), Q6 *repeats* Q1 (id живут вне снапшота).

**Матрица покрытия** (оси × стадии: init / read / write / commit / reopen)

| Ось | init | read | write | commit | reopen |
|---|---|---|---|---|---|
| входы | `path`/`None` → `_load_journal` | `where`/`None` → `_matches` | row/changes → deepcopy | — | путь → replay |
| данные | JSON+unicode → `ensure_ascii=False` | `_id`-сортировка | `_TOMB`, `_local` | `ops`+`idc` | `_row_ver` восстанавливается |
| отказы | битый хвост → truncate | — | `_id`→`ValueError`, dead→`RuntimeError` | конфликт→`ConflictError` | битая запись → игнор |
| контракты | идемпотентный `close` | копии через `deepcopy` | автосоздание таблицы | журнал→fsync→память | все коммиты на месте |
| доставка | `__all__` | `select` | `insert/update/delete` | `commit/rollback` | `Database(path)` |

**Реестр отложенного**

| Что | Статус | Причина | Куда |
|---|---|---|---|
| Многопроцессный доступ к одному файлу | не поддерживается | нет file-lock в ТЗ | задокументировано в docstring |
| `_id` из входа `insert` | перезаписывается | `_id` выдаёт БД (п.3) | `insert()` |
| `update` с пустым `changes` | no-op, возвращает счётчик совпадений | избежать ложных конфликтов | `update()` |
| `rollback()` после `ConflictError` | разрешён | уборка мусора, ТЗ не запрещает | `rollback()` |
| `begin()` после `close()` | `RuntimeError` | база закрыта | `begin()` |
| не-строковые ключи в dict | станут строками (JSON-семантика) | ТЗ: только JSON-совместимые | docstring |

---

```python
"""Мини-СУБД на чистом Python: снимок-изоляция, оптимистичные конфликты,
append-only журнал с CRC на каждую запись.

Публичный API:
    Database(path=None)          - persistent / in-memory база
    db.begin() -> Transaction
    tx.insert(table, row) -> int
    tx.select(table, where=None) -> list[dict]
    tx.update(table, where, changes) -> int
    tx.delete(table, where) -> int
    tx.commit() / tx.rollback()
    db.close()

Замечания по контракту:
  * значения строк должны быть JSON-совместимыми; не-строковые ключи
    вложенных dict сериализуются как строки (семантика JSON);
  * одновременная работа нескольких процессов с одним файлом журнала
    не поддерживается (нет file-lock);
  * после Database.close() повторный close() - no-op, begin() - RuntimeError.
"""

from __future__ import annotations

import copy
import json
import os
import threading
import zlib

__all__ = ["Database", "Transaction", "ConflictError"]


class ConflictError(Exception):
    """Строку изменила/удалила чужая зафиксированная транзакция после нашего begin()."""


#: маркер удаления строки в локальном overlay транзакции
_TOMB = object()


# --------------------------------------------------------------------------
# сравнение значений в where
# --------------------------------------------------------------------------
def _eq(a, b):
    """Точное совпадение с разделением bool/int (в JSON true != 1)."""
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    return a == b


def _matches(row, where):
    for key, value in where.items():
        if key not in row:
            return False
        if not _eq(row[key], value):
            return False
    return True


# --------------------------------------------------------------------------
# формат журнала:  <json-utf8> \t <crc32 hex 8> \n
# --------------------------------------------------------------------------
def _encode_record(rec):
    body = json.dumps(rec, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    crc = zlib.crc32(body) & 0xFFFFFFFF
    return body + b"\t" + ("%08x" % crc).encode("ascii") + b"\n"


def _decode_line(line):
    """line - байты без завершающего b'\\n'. Возвращает dict или None."""
    body, sep, crc_part = line.rpartition(b"\t")
    if not sep or len(crc_part) != 8:
        return None
    try:
        expected = int(crc_part, 16)
    except (TypeError, ValueError):
        return None
    if (zlib.crc32(body) & 0xFFFFFFFF) != expected:
        return None
    try:
        rec = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None
    return rec if isinstance(rec, dict) else None


def _record_ok(rec):
    if not isinstance(rec, dict):
        return False
    seq = rec.get("seq")
    if not isinstance(seq, int) or isinstance(seq, bool) or seq < 0:
        return False
    idc = rec.get("idc", 1)
    if not isinstance(idc, int) or isinstance(idc, bool) or idc < 0:
        return False
    ops = rec.get("ops", [])
    if not isinstance(ops, list):
        return False
    for op in ops:
        if not isinstance(op, list) or len(op) < 3:
            return False
        kind = op[0]
        if kind not in ("i", "u", "d"):
            return False
        if not isinstance(op[1], str):
            return False
        rid = op[2]
        if not isinstance(rid, int) or isinstance(rid, bool) or rid <= 0:
            return False
        if kind in ("i", "u"):
            if len(op) != 4 or not isinstance(op[3], dict):
                return False
        elif len(op) != 3:
            return False
    return True


def _replay(rec, state):
    """Применить валидную запись к состоянию (без исключений)."""
    seq = rec["seq"]
    for op in rec.get("ops", []):
        kind, table, rid = op[0], op[1], op[2]
        if kind == "d":
            tbl = state["tables"].get(table)
            if tbl is not None:
                tbl.pop(rid, None)
        else:
            row = dict(op[3])
            row["_id"] = rid
            state["tables"].setdefault(table, {})[rid] = row
        state["row_ver"][(table, rid)] = seq
        if rid + 1 > state["next_id"]:
            state["next_id"] = rid + 1
    if seq > state["seq"]:
        state["seq"] = seq
    idc = rec.get("idc", 0)
    if isinstance(idc, int) and not isinstance(idc, bool) and idc > state["idc"]:
        state["idc"] = idc
    if state["idc"] > state["next_id"]:
        state["next_id"] = state["idc"]


def _load_journal(path):
    state = {"tables": {}, "row_ver": {}, "next_id": 1, "seq": 0, "idc": 1}
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except FileNotFoundError:
        return state

    valid_end = 0
    pos = 0
    total = len(data)
    while True:
        nl = data.find(b"\n", pos)
        if nl < 0:              # незавершённая (обрезанная) запись
            break
        rec = _decode_line(data[pos:nl])
        if rec is None or not _record_ok(rec):
            break               # мусор / битый CRC -> всё дальнейшее игнорируем
        _replay(rec, state)
        pos = nl + 1
        valid_end = pos

    if valid_end < total:
        # отрезаем хвост, чтобы будущие append'ы не оказались "за мусором"
        try:
            with open(path, "r+b") as fh:
                fh.truncate(valid_end)
                fh.flush()
                os.fsync(fh.fileno())
        except OSError:
            pass
    return state


# --------------------------------------------------------------------------
# Database
# --------------------------------------------------------------------------
class Database:
    def __init__(self, path=None):
        self._path = None if path is None else os.fspath(path)
        self._lock = threading.RLock()
        self._closed = False
        self._file = None

        if self._path is None:
            self._tables = {}       # table -> {_id: row}
            self._row_ver = {}      # (table, _id) -> seq последнего изменения
            self._next_id = 1
            self._seq = 0
            self._persisted_idc = 1
        else:
            state = _load_journal(self._path)
            self._tables = state["tables"]
            self._row_ver = state["row_ver"]
            self._next_id = state["next_id"]
            self._seq = state["seq"]
            self._persisted_idc = state["idc"]

    # -- служебное ---------------------------------------------------------
    @property
    def closed(self):
        return self._closed

    def _alloc_id(self):
        with self._lock:
            rid = self._next_id
            self._next_id += 1
            return rid

    def _write_record(self, rec):
        if self._path is None:
            return
        data = _encode_record(rec)
        fh = self._file
        if fh is None:
            fh = open(self._path, "ab")
            self._file = fh
        fh.write(data)
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except OSError:
            pass

    def _apply_committed(self, ops, seq):
        """Применить зафиксированные операции к разделяемой памяти БД."""
        for op in ops:
            kind, table, rid = op[0], op[1], op[2]
            if kind == "d":
                tbl = self._tables.get(table)
                if tbl is not None:
                    tbl.pop(rid, None)
            else:
                row = dict(op[3])
                row["_id"] = rid
                self._tables.setdefault(table, {})[rid] = row
            self._row_ver[(table, rid)] = seq
        self._seq = seq

    # -- публичное ---------------------------------------------------------
    def begin(self):
        with self._lock:
            if self._closed:
                raise RuntimeError("database is closed")
            return Transaction(self)

    def close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            try:
                # зафиксировать счётчик _id, чтобы выданные (даже откаченные)
                # идентификаторы не были переиспользованы после переоткрытия
                if self._path is not None and self._next_id > self._persisted_idc:
                    rec = {"seq": self._seq + 1, "ops": [], "idc": self._next_id}
                    self._write_record(rec)
                    self._seq += 1
                    self._persisted_idc = self._next_id
            finally:
                fh = self._file
                self._file = None
                if fh is not None:
                    try:
                        fh.close()
                    except OSError:
                        pass

    def __repr__(self):
        kind = "memory" if self._path is None else self._path
        return "<Database %s tables=%d seq=%d>" % (kind, len(self._tables), self._seq)


# --------------------------------------------------------------------------
# Transaction
# --------------------------------------------------------------------------
class Transaction:
    def __init__(self, db):
        self._db = db
        self._state = "active"          # active | committed | rolledback | conflicted
        self._start_seq = db._seq
        # снимок: копируем только словари таблиц, строки неизменяемы
        self._base = {name: dict(rows) for name, rows in db._tables.items()}
        self._local = {}                # table -> {_id: row | _TOMB}
        self._touched = set()           # (table, _id), которые мы меняем/удаляем

    @property
    def state(self):
        return self._state

    # -- служебное ---------------------------------------------------------
    def _check_alive(self):
        if self._state != "active":
            raise RuntimeError(
                "transaction is not active (state=%r)" % (self._state,)
            )

    def _view(self, table):
        """Снимок на begin() + собственные записи транзакции."""
        rows = dict(self._base.get(table, ()))
        loc = self._local.get(table)
        if loc:
            for rid, value in loc.items():
                if value is _TOMB:
                    rows.pop(rid, None)
                else:
                    rows[rid] = value
        return rows

    def _build_ops(self):
        ops = []
        for table in sorted(self._local):
            base_t = self._base.get(table, {})
            loc = self._local[table]
            for rid in sorted(loc):
                value = loc[rid]
                if value is _TOMB:
                    if rid in base_t:              # удаление существующей строки
                        ops.append(["d", table, rid])
                    continue                       # вставили и удалили — не пишем
                kind = "u" if rid in base_t else "i"
                ops.append([kind, table, rid, value])
        return ops

    # -- чтение (разрешено в любом состоянии) ------------------------------
    def select(self, table, where=None):
        cond = where or {}
        rows = self._view(table)
        result = []
        for rid in sorted(rows):
            row = rows[rid]
            if _matches(row, cond):
                result.append(copy.deepcopy(row))
        return result

    # -- запись ------------------------------------------------------------
    def insert(self, table, row):
        self._check_alive()
        rid = self._db._alloc_id()
        new_row = copy.deepcopy(dict(row))
        new_row["_id"] = rid
        self._local.setdefault(table, {})[rid] = new_row
        return rid

    def update(self, table, where, changes):
        self._check_alive()
        if "_id" in changes:
            raise ValueError("cannot change _id")

        rows = self._view(table)
        targets = [rid for rid in sorted(rows) if _matches(rows[rid], where or {})]
        if not changes:
            # no-op: не порождаем ни версий, ни ложных конфликтов
            return len(targets)

        pending = copy.deepcopy(dict(changes))
        loc = self._local.setdefault(table, {})
        for rid in targets:
            new_row = dict(rows[rid])
            new_row.update(copy.deepcopy(pending))
            new_row["_id"] = rid
            loc[rid] = new_row
            self._touched.add((table, rid))
        return len(targets)

    def delete(self, table, where):
        self._check_alive()
        rows = self._view(table)
        targets = [rid for rid in sorted(rows) if _matches(rows[rid], where or {})]
        loc = self._local.setdefault(table, {})
        for rid in targets:
            loc[rid] = _TOMB
            self._touched.add((table, rid))
        return len(targets)

    # -- завершение --------------------------------------------------------
    def commit(self):
        db = self._db
        with db._lock:
            self._check_alive()

            # 1. проверка конфликтов ДО записи в журнал
            for table, rid in sorted(self._touched):
                current = db._row_ver.get((table, rid), 0)
                if current > self._start_seq:
                    self._state = "conflicted"
                    raise ConflictError(
                        "row _id=%r in table %r was modified by another "
                        "committed transaction" % (rid, table)
                    )

            ops = self._build_ops()
            if ops:
                new_seq = db._seq + 1
                rec = {"seq": new_seq, "ops": ops, "idc": db._next_id}
                # 2. журнал на диск (write + flush + fsync)
                db._write_record(rec)
                # 3. и только потом — память
                db._apply_committed(ops, new_seq)
                db._persisted_idc = rec["idc"]

            self._state = "committed"

    def rollback(self):
        if self._state in ("committed", "rolledback"):
            raise RuntimeError("transaction is already finished")
        self._local.clear()
        self._touched.clear()
        self._state = "rolledback"

    def __repr__(self):
        return "<Transaction %s start_seq=%d touched=%d>" % (
            self._state, self._start_seq, len(self._touched)
        )
