            raise RuntimeError(
                "transaction is already committed or rolled back"
            )

    @property
    def finished(self):
        """``True``, если транзакция зафиксирована или откатана (чтение)."""
        return self._done

    def _touched_rows(self):
        """Уникальные (table, _id), которые транзакция меняет или удаляет."""
        seen = set()
        touched = []
        for op in self._ops:
            if op["op"] == "insert":
