            raise TypeError("table must be a str")
        if not isinstance(row, dict):
            raise TypeError("row must be a dict")

        row_id = self._db._alloc_id()
        new_row = copy.deepcopy(row)
        new_row["_id"] = row_id

        self._view.setdefault(table, {})[row_id] = new_row
        self._ops.append(
            {"op": "insert", "table": table, "row": copy.deepcopy(new_row)}
        )
        self._inserted.add((table, row_id))
        return row_id

    def select(self, table, where=None):
        """Строки, подходящие по всем парам ``where``, по возрастанию ``_id``.

        Возвращаются копии. Чтение разрешено и после commit/rollback.
        """
        if where is None:
            where = {}
        if not isinstance(where, dict):
            raise TypeError("where must be a dict or None")

        rows = self._view.get(table)
        if not rows:
            return []
        return [
            copy.deepcopy(rows[row_id])
            for row_id in sorted(rows)
            if _matches(rows[row_id], where)
        ]

    def update(self, table, where, changes):
        """Изменить подходящие строки; вернуть их число. ``_id`` менять нельзя."""
        self._check_alive()
        if where is None:
            where = {}
