            raise TypeError("changes must be a dict")
        if "_id" in changes:
            raise ValueError("_id cannot be changed")

        rows = self._view.get(table)
        if not rows:
            return 0

        patch = copy.deepcopy(changes)
        affected = [
            row_id for row_id in sorted(rows) if _matches(rows[row_id], where)
        ]
        for row_id in affected:
            new_row = copy.deepcopy(rows[row_id])
            new_row.update(copy.deepcopy(patch))
            new_row["_id"] = row_id
            rows[row_id] = new_row
