        seq = db._seq + 1
        record = {
            "type": "commit",
            "seq": seq,
            "next_id": db._next_id,
            "ops": copy.deepcopy(self._ops),
        }
        db._append_record(record)

        # 3) применение к памяти
        db._apply_commit(seq, record["ops"])
        if db._next_id > db._persisted_next_id:
            db._persisted_next_id = db._next_id

        self._done = True

    def rollback(self):
